190	/****************************************************************************
191	 * fb_init_mem2
192	 ****************************************************************************/
193	
194	static int fb_init_mem2(FAR struct fb_state_s *state)
195	{
196	  struct fb_planeinfo_s pinfo;
197	  FAR void * phy_mem1;
198	  FAR void * phy_mem2;
199	  bool is_consecutive;
200	  off_t offset;
201	  uint32_t fblen;
202	  int ret;
203	
204	  /* Get display[0] planeinfo */
205	
206	  memset(&pinfo, 0, sizeof(pinfo));
207	  pinfo.display = state->pinfo.display;
208	
209	  if ((ret = fbdev_get_pinfo(state->fd, &pinfo)) < 0)
210	    {
211	      return ret;
212	    }
213	
214	  phy_mem1 = pinfo.fbmem;
215	
216	  /* Get display[1] planeinfo */
217	
218	  memset(&pinfo, 0, sizeof(pinfo));
219	  pinfo.display = state->pinfo.display + 1;
220	
221	  if ((ret = fbdev_get_pinfo(state->fd, &pinfo)) < 0)
222	    {
223	      return ret;
224	    }
225	
226	  phy_mem2 = pinfo.fbmem;
227	
228	  offset = (off_t)((uintptr_t)phy_mem2 - (uintptr_t)phy_mem1);
229	  is_consecutive = offset == 0;
230	
231	  /* Check bpp */
232	
233	  if (pinfo.bpp != state->pinfo.bpp)
234	    {
235	      fprintf(stderr, "ERROR: fbmem2 is incorrect");
236	      return -EINVAL;
237	    }
238	
239	  /* Check the buffer address offset,
240	   * It needs to be divisible by pinfo.stride
241	   */
242	
243	  if ((offset % state->pinfo.stride) != 0)
244	    {
245	      fprintf(stderr, "ERROR: It is detected that buf_offset(%lld) "
246	              "and stride(%d) are not divisible, please ensure "
247	              "that the driver handles the address offset by itself.\n",
248	              (long long)offset, state->pinfo.stride);
249	    }
250	
251	  /* Calculate the address and yoffset of fbmem2 */
252	
253	  if (is_consecutive)
254	    {
255	      state->mem2_yoffset = state->vinfo.yres;
256	      offset = (off_t)state->vinfo.yres * pinfo.stride;
257	    }
258	  else
259	    {
260	      state->mem2_yoffset = offset / state->pinfo.stride;
261	    }
262	
263	  fblen = is_consecutive ? pinfo.fblen / 2 : pinfo.fblen;
264	  void * mem2 = mmap(NULL, fblen,
265	                    PROT_READ | PROT_WRITE,
266	                    MAP_SHARED | MAP_FILE,
267	                    state->fd, offset);
268	
269	  if (mem2 == MAP_FAILED)
270	    {
271	      fprintf(stderr, "ERROR: mmap failed: %d, offset: %lld\n",
272	            errno, (long long)offset);
273	      return -errno;
274	    }
275	
276	  state->fbmem2 = mem2;
277	  fprintf(stderr, "Use of %sconsecutive mem2 = %p, yoffset = %" PRIu32 "\n",
278	          is_consecutive ? "" : "non-", state->fbmem2,
279	          state->mem2_yoffset);
280	
281	  return 0;
282	}
