374	static void draw_rect1(FAR struct fb_state_s *state,
375	                       FAR struct fb_area_s *area, int color)
376	{
377	  FAR uint8_t *pixel;
378	  FAR uint8_t *row;
379	  uint8_t color8 = (color & 1) == 0 ? 0 : 0xff;
380	
381	  int start_full_x;
382	  int end_full_x;
383	  int start_bit_shift;
384	  int last_bits;
385	  uint8_t lmask;
386	  uint8_t rmask;
387	  int y;
388	
389	  /* Calculate the framebuffer address of the first row to draw on */
390	
391	  row    = (FAR uint8_t *)state->act_fbmem + state->pinfo.stride * area->y;
392	
393	  /* Calculate the position of the first complete (with all bits) byte.
394	   * Then calculate the last byte with all the bits.
395	   */
396	
397	  start_full_x = ((area->x + 7) >> 3);
398	  end_full_x   = ((area->x + area->w) >> 3);
399	
400	  /* Calculate the number of bits in byte before start that need to remain
401	   * unchanged. Later calculate the mask.
402	   */
403	
404	  start_bit_shift = 8 + area->x - (start_full_x << 3);
405	  lmask = 0xff >> start_bit_shift;
406	
407	  /* Calculate the number of bits that needs to be changed after last byte
408	   * with all the bits. Later calculate the mask.
409	   */
410	
411	  last_bits = area->x + area->w - (end_full_x << 3);
412	  rmask = 0xff << (8 - last_bits);
413	
414	  /* Calculate a mask on the first and last bytes of the sequence that may
415	   * not be completely filled with pixel.
416	   */
417	
418	  /* Now draw each row, one-at-a-time */
419	
420	  for (y = 0; y < area->h; y++)
421	    {
422	      /* 'pixel' points to the 1st pixel the next row */
423	
424	      /* Special case: The row starts and ends within the same byte */
425	
426	      if (start_full_x > end_full_x)
427	        {
428	          pixel = row + start_full_x - 1;
429	          *pixel = (*pixel & (~lmask | ~rmask)) | (lmask & rmask & color8);
430	          continue;
431	        }
432	
433	      if (start_bit_shift != 0)
434	        {
435	          pixel = row + start_full_x - 1;
436	          *pixel = (*pixel & ~lmask) | (lmask & color8);
437	        }
438	
439	      if (end_full_x > start_full_x)
440	        {
441	          pixel = row + start_full_x;
442	          memset(pixel, color8, end_full_x - start_full_x);
443	        }
444	
445	      if (last_bits != 0)
446	        {
447	          pixel = row + end_full_x;
448	          *pixel = (*pixel & ~rmask) | (rmask & color8);
449	        }
450	
451	      row += state->pinfo.stride;
452	    }
453	}
