455	static void draw_rect(FAR struct fb_state_s *state,
456	                      FAR struct fb_area_s *area, int color)
457	{
458	#ifdef CONFIG_FB_UPDATE
459	  int ret;
460	#endif
461	
462	  switch (state->pinfo.bpp)
463	    {
464	      case 32:
465	        draw_rect32(state, area, color);
466	        break;
467	
468	      case 24:
469	        draw_rect24(state, area, color);
470	        break;
471	
472	      case 16:
473	        draw_rect16(state, area, color);
474	        break;
475	
476	      case 8:
477	      default:
478	        draw_rect8(state, area, color);
479	        break;
480	
481	      case 1:
482	        draw_rect1(state, area, color);
483	        break;
484	    }
485	
486	#ifdef CONFIG_FB_UPDATE
487	  int yoffset = state->act_fbmem == state->fbmem ?
488	                0 : state->mem2_yoffset;
489	  area->y += yoffset;
490	
491	  ret = ioctl(state->fd, FBIO_UPDATE,
492	              (unsigned long)((uintptr_t)area));
493	  if (ret < 0)
494	    {
495	      int errcode = errno;
496	      fprintf(stderr, "ERROR: ioctl(FBIO_UPDATE) failed: %d\n",
497	              errcode);
498	    }
499	#endif
500	
501	  if (state->pinfo.yres_virtual == (state->vinfo.yres * 2))
502	    {
503	      pan_display(state);
