static void ltdc_configure_clocks(void)
{
  /* Enable LTDC peripheral clock (LTDC is on APB5) */

  rcc_enable_apb5_clock(RCC_APB5ENR_LTDCEN);

  /* Configure LTDC pixel clock via IC16
   * Clock chain: PLL4 -> IC16 -> LTDC
   * PLL4 runs at 1600MHz (HSI=64MHz * 25 = 1600MHz)
   * For 800x480 panel: pixel clock = 25 MHz
   * IC16 divider = 1600 / 25 = 64
   *
   * Reference: STM32N6570-DK LTDC example (stm32n6xx_hal_msp.c:92-114)
   * PLL1_VCO Input = HSI_VALUE = 64 Mhz
   * PLL1_VCO Output = PLL1_VCO Input * PLLN / DIVM = 64 Mhz * 25 = 1600
   * PLLLCDCLK = PLL1_VCO Output/64 = 1600/64 = 25Mhz
   * LTDC clock frequency = PLLLCDCLK = 25 Mhz
   */

  /* IC16CFGR: IC16 source = PLL4, divider = 64 */

  modifyreg32(STM32_RCC_BASE + RCC_IC16CFGR_OFFSET, 0,
               RCC_IC16CFGR_IC16SRC_PLL4 | (64 << RCC_IC16CFGR_IC16DIV_SHIFT));

  /* Select IC16 as LTDC clock source */

  modifyreg32(STM32_RCC_BASE + RCC_CCIPR5_OFFSET, RCC_CCIPR5_LTDCSEL_MASK,
               RCC_CCIPR5_LTDCSEL_IC16);
}

