  reg = RCC_PLL4CFGR1_PLL4SEL_HSI |
        ((4 - 1) << 4) |    /* DIVM4: bits 7:4 */
        ((25 - 1) << 8);    /* DIVN4: bits 15:8 */
  rcc_set_pll4cfgr(reg);

